using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Diagnostics;using System.Runtime.InteropServices;using System.Collections.Generic;using Forms=System.Windows.Forms;
namespace InputAtlas {
public sealed class NativeInputWindow:Forms.NativeWindow,IDisposable {
 [StructLayout(LayoutKind.Sequential)]struct RawDevice{public ushort Page,Usage;public uint Flags;public IntPtr Target;}
 [StructLayout(LayoutKind.Sequential)]struct Header{public uint Type,Size;public IntPtr Device,WParam;}
 [StructLayout(LayoutKind.Sequential)]struct Point{public int X,Y;}
 [StructLayout(LayoutKind.Sequential)]struct Rect{public int Left,Top,Right,Bottom;}
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct MonitorInfo{public uint Size;public Rect Bounds,Work;public uint Flags;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=32)]public string Device;}
 [StructLayout(LayoutKind.Sequential)]struct LastInput{public uint Size,Time;}
 [DllImport("user32.dll",SetLastError=true)]static extern bool RegisterRawInputDevices(RawDevice[] devices,uint count,uint size);
 [DllImport("user32.dll")]static extern uint GetRawInputData(IntPtr input,uint command,IntPtr data,ref uint size,uint header);
 [DllImport("user32.dll")]static extern bool GetCursorPos(out Point point);
 [DllImport("user32.dll")]static extern IntPtr MonitorFromPoint(Point point,uint flags);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool GetMonitorInfo(IntPtr monitor,ref MonitorInfo info);
 [DllImport("user32.dll")]static extern bool GetLastInputInfo(ref LastInput info);
 [DllImport("user32.dll")]static extern int GetMessageTime();
 [DllImport("user32.dll")]static extern short GetAsyncKeyState(int key);
 [DllImport("kernel32.dll")]static extern ulong GetTickCount64();
 readonly NetworkSourceProbe networkSources=new NetworkSourceProbe();string[] currentNetworks=new string[0];string sourceError="";
 readonly NativeInputStore storage;readonly NativeInputModel model=new NativeInputModel();readonly ForegroundResolver foreground=new ForegroundResolver();readonly Forms.Timer timer=new Forms.Timer();readonly Stopwatch clock=Stopwatch.StartNew();readonly HashSet<string> displays=new HashSet<string>();readonly string root;NativeInputOptions options;IntPtr raw;DateTime previous=DateTime.Now;long nextFlush,lastRaw,nextOptions;string app="Unknown",error="",networkError="";bool disposed;readonly double runSeconds;
 public NativeInputWindow(double seconds=0){runSeconds=seconds;root=Store.Root;storage=new NativeInputStore(Path.Combine(root,"inputatlas.sqlite"));options=NativeInputOptions.Load(root);CreateHandle(new Forms.CreateParams{Caption="Native keyboard and mouse statistics",Parent=(IntPtr)(-3)});raw=Marshal.AllocHGlobal(65536);var devices=new[]{new RawDevice{Page=1,Usage=6,Flags=0x2100,Target=Handle},new RawDevice{Page=1,Usage=2,Flags=0x2100,Target=Handle}};if(!RegisterRawInputDevices(devices,2,(uint)Marshal.SizeOf(typeof(RawDevice))))throw new IOException("Raw Input registration: "+Marshal.GetLastWin32Error());timer.Interval=250;timer.Tick+=(s,e)=>Tick();timer.Start();Tick();}
 void PointForClick(DateTime at,int button){Point p;if(!GetCursorPos(out p))return;var info=new MonitorInfo{Size=(uint)Marshal.SizeOf(typeof(MonitorInfo))};if(!GetMonitorInfo(MonitorFromPoint(p,2),ref info))return;int width=info.Bounds.Right-info.Bounds.Left,height=info.Bounds.Bottom-info.Bounds.Top;if(width<=0||height<=0)return;string id=info.Device+"|"+width+"x"+height;if(displays.Add(id))storage.Display(id,width,height,info.Bounds.Left,info.Bounds.Top);model.Click(at,foreground.Read(),button,id,(int)((p.X-info.Bounds.Left)*128L/width),(int)((p.Y-info.Bounds.Top)*72L/height));}
 protected override void WndProc(ref Forms.Message message){try{if(message.Msg==0x00FF)Read(message.LParam);else if(message.Msg==0x00FE)model.ResetEdges();}catch(Exception ex){error=ex.Message;}finally{base.WndProc(ref message);}}
 void Read(IntPtr input){lastRaw=clock.ElapsedMilliseconds;if(unchecked((uint)(Environment.TickCount-GetMessageTime()))>2000){model.ResetEdges();return;}uint size=0,header=(uint)Marshal.SizeOf(typeof(Header));if(GetRawInputData(input,0x10000003,IntPtr.Zero,ref size,header)==UInt32.MaxValue||size>65536||size<header+16)return;if(GetRawInputData(input,0x10000003,raw,ref size,header)==UInt32.MaxValue)return;var h=(Header)Marshal.PtrToStructure(raw,typeof(Header));int o=(int)header;DateTime at=DateTime.Now;if(h.Type==1){model.Key(h.Device.ToInt64(),(ushort)Marshal.ReadInt16(raw,o+6),(ushort)Marshal.ReadInt16(raw,o),(ushort)Marshal.ReadInt16(raw,o+2),at,foreground.Read());}else if(h.Type==0&&size>=header+24){int flags=(ushort)Marshal.ReadInt16(raw,o+4);int[] down={1,4,16,64,256};for(int i=0;i<down.Length;i++)if((flags&down[i])!=0)PointForClick(at,i+1);if((flags&(0x400|0x800))!=0)model.Scroll(at,foreground.Read(),Marshal.ReadInt16(raw,o+6));if((((ushort)Marshal.ReadInt16(raw,o))&1)==0){double x=Marshal.ReadInt32(raw,o+12),y=Marshal.ReadInt32(raw,o+16);model.Move(at,app,Math.Sqrt(x*x+y*y)/options.MouseDpi);}}}
 void Heartbeat(){string p=Path.Combine(root,"collector-heartbeat.json"),tmp=p+".native-input.tmp";double at=new DateTimeOffset(DateTime.Now).ToUnixTimeMilliseconds()/1000.0;File.WriteAllText(tmp,Store.Json.Serialize(new{pid=Process.GetCurrentProcess().Id,at=at,api_at=at,sample_at=at,error=error,network_error=networkError,engine="Native Raw Input + IP Helper",keys=model.TotalKeys,clicks=model.TotalClicks,shortcuts=model.TotalShortcuts,current_networks=currentNetworks,network_source_error=sourceError,mouse_dpi=options.MouseDpi}));if(File.Exists(p))File.Replace(tmp,p,null);else File.Move(tmp,p);}
 void Flush(){DateTime now=DateTime.Now;var idle=new LastInput{Size=(uint)Marshal.SizeOf(typeof(LastInput))};double seconds=GetLastInputInfo(ref idle)?unchecked((uint)Environment.TickCount-idle.Time)/1000.0:-1;List<MonitorMetrics.IfRow> rows=null;Dictionary<string,NetworkOrigin> origins=null;try{rows=MonitorMetrics.Enumerate();origins=networkSources.Capture(rows);currentNetworks=origins.Values.Where(v=>v.Kind!="unknown").Select(v=>v.Name).Distinct().ToArray();sourceError=networkSources.LastError;networkError="";}catch(Exception ex){networkError=ex.Message;}storage.Flush(model,previous,now,app,seconds,rows,new DateTimeOffset(DateTime.UtcNow).ToUnixTimeMilliseconds()/1000.0-GetTickCount64()/1000.0,origins);previous=now;error="";Heartbeat();}
 void Tick(){try{app=foreground.Read();long now=clock.ElapsedMilliseconds;if(networkSources.ConsumeChange())nextFlush=0;if(now-lastRaw>5000)model.PruneReleasedKeys(k=>(GetAsyncKeyState(k)&0x8000)!=0);if(now>=nextOptions){options=NativeInputOptions.Load(root);nextOptions=now+5000;}if(now>=nextFlush){Flush();nextFlush=now+2000;}if(File.Exists(Path.Combine(root,"collector.stop"))||(runSeconds>0&&clock.Elapsed.TotalSeconds>=runSeconds))Forms.Application.ExitThread();}catch(Exception ex){error=ex.Message;try{Heartbeat();}catch{}}}
 public void Dispose(){if(disposed)return;disposed=true;timer.Stop();try{Flush();}catch{}RegisterRawInputDevices(new[]{new RawDevice{Page=1,Usage=6,Flags=1},new RawDevice{Page=1,Usage=2,Flags=1}},2,(uint)Marshal.SizeOf(typeof(RawDevice)));foreground.Dispose();networkSources.Dispose();storage.Dispose();if(raw!=IntPtr.Zero)Marshal.FreeHGlobal(raw);DestroyHandle();timer.Dispose();}
}
public static class NativeInputEntry {
 [DllImport("user32.dll")]static extern bool SetProcessDpiAwarenessContext(IntPtr context);
 [STAThread]public static int Main(string[] args){try{NativeRuntime.Configure();bool owned;using(var mutex=new Mutex(true,args.Length==2&&args[0]=="--probe-seconds"&&Store.Root.IndexOf("tests",StringComparison.OrdinalIgnoreCase)>=0?MonitorOptions.Name(Store.Root,"native-input-test"):NativeRuntime.Name("basic-collector"),out owned)){if(!owned)return 0;SetProcessDpiAwarenessContext((IntPtr)(-4));using(var window=new NativeInputWindow(args.Length==2&&args[0]=="--probe-seconds"&&Store.Root.IndexOf("tests",StringComparison.OrdinalIgnoreCase)>=0?Math.Max(1,Math.Min(120,Double.Parse(args[1]))):0))Forms.Application.Run();}return 0;}catch(Exception ex){try{File.AppendAllText(Path.Combine(Store.Root,"native-input-error.log"),DateTime.Now.ToString("o")+" "+ex+Environment.NewLine);}catch{}return 1;}}
}
}
